var n=`0940-tonkotsu-ramen`;var t=`world-0940`;var s=`JP`;var r=`east-asia`;var o=4;var a=308;var l={en:`Tonkotsu Ramen`,ua:`Тонкоцу рамен`};var g={en:`Tonkotsu Ramen is a Japan dish made with pork bones, garlic, pork belly, light soy sauce. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Тонкоцу рамен, страва кухні країни Японія. Основні складники: свинячі кістки, часник, свиняча грудинка, світлий соєвий соус. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var m=[{en:`Simmer cleaned pork bones for several hours, topping up water as required, then strain for creamy tonkotsu broth.`,ua:`Варіть очищені свинячі кістки кілька годин, доливаючи воду за потреби, тоді процідіть для насиченого бульйону тонкоцу.`,t:[`simmering`,`skimming-foam`],m:240,i:[[`pork-bones`,1500,`g`],[`water`,2600,`ml`],[`ground-ginger`,35,`g`],[`garlic`,6,`clove`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 45 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 45 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:45,i:[[`pork-belly`,450,`g`],[`light-soy-sauce`,45,`ml`],[`mirin`,40,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 6 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 6 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:6,i:[[`ramen-noodles`,430,`g`]]},{en:`Boil the eggs for about 9 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 9 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:9,i:[[`chicken-egg`,4,`pcs`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:8,i:[[`green-onion`,70,`g`],[`nori`,4,`pcs`]]}];var u={slug:n,id:t,country:`JP`,region:r,servings:4,minutes:308,title:l,text:g,steps:m};export{s as country,u as default,t as id,a as minutes,r as region,o as servings,n as slug,m as steps,g as text,l as title};